class Solution {
public:
    int largestMagicSquare(vector<vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();

        vector<vector<int>> rowSum(m, vector<int>(n + 1, 0));
        vector<vector<int>> colSum(m + 1, vector<int>(n, 0));
        vector<vector<int>> diag1(m + 1, vector<int>(n + 1, 0));
        vector<vector<int>> diag2(m + 1, vector<int>(n + 1, 0));

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                rowSum[i][j + 1] = rowSum[i][j] + grid[i][j];
                colSum[i + 1][j] = colSum[i][j] + grid[i][j];
                diag1[i + 1][j + 1] = diag1[i][j] + grid[i][j];
                diag2[i + 1][j] = diag2[i][j + 1] + grid[i][j];
            }
        }

        int maxSize = 1;

        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                int maxK = min(m - r, n - c);
                for (int k = maxK; k >= 2; k--) {
                    int br = r + k - 1;
                    int bc = c + k - 1;

                    int d1 = diag1[br + 1][bc + 1] - diag1[r][c];
                    int d2 = diag2[br + 1][c] - diag2[r][bc + 1];

                    if (d1 != d2) continue;

                    int target = d1;
                    bool ok = true;

                    for (int i = r; i <= br && ok; i++) {
                        if (rowSum[i][bc + 1] - rowSum[i][c] != target)
                            ok = false;
                    }
                    for (int j = c; j <= bc && ok; j++) {
                        if (colSum[br + 1][j] - colSum[r][j] != target)
                            ok = false;
                    }

                    if (ok) {
                        maxSize = max(maxSize, k);
                        break;
                    }
                }
            }
        }

        return maxSize;
    }
};
